// ============================================
// INITIALIZE EXPIRATION JOB
// ============================================

const now = new Date();
const in7Days = new Date(now);
in7Days.setDate(in7Days.getDate() + 7);

return {
  job_id: `expiration-${Date.now()}`,
  run_date: now.toISOString(),
  warning_date: in7Days.toISOString().split('T')[0], // Date only for 7-day warning
  today: now.toISOString().split('T')[0]
};

// ============================================
// CATEGORIZE EXPIRING ACCESS
// ============================================

const response = $input.first().json;
const jobData = $('Initialize Job').first().json;
const today = new Date(jobData.today);

const accessRecords = response.data || response || [];
const records = Array.isArray(accessRecords) ? accessRecords : [];

// Categorize by expiration status
const expired = [];       // Already expired
const expiringToday = []; // Expires today
const expiring7Days = []; // Expires in next 7 days

for (const record of records) {
  if (!record.expires_at) continue;

  const expiresAt = new Date(record.expires_at);
  const daysUntilExpiration = Math.ceil((expiresAt - today) / (1000 * 60 * 60 * 24));

  if (daysUntilExpiration <= 0) {
    expired.push({ ...record, days_until: daysUntilExpiration });
  } else if (daysUntilExpiration === 1) {
    expiringToday.push({ ...record, days_until: daysUntilExpiration });
  } else {
    expiring7Days.push({ ...record, days_until: daysUntilExpiration });
  }
}

return {
  job_id: jobData.job_id,
  run_date: jobData.run_date,
  total_checked: records.length,
  expired: expired,
  expiring_today: expiringToday,
  expiring_7_days: expiring7Days,
  expired_count: expired.length,
  expiring_today_count: expiringToday.length,
  expiring_7_days_count: expiring7Days.length
};

// ============================================
// PREPARE EXPIRED RECORDS FOR PROCESSING
// ============================================

const data = $input.first().json;

// Return each expired record for batch processing
return data.expired.map(record => ({
  job_id: data.job_id,
  access_id: record.id,
  user_id: record.user_id,
  discord_id: record.discord_id,
  guild_id: record.guild_id,
  course_id: record.course_id,
  stripe_product_id: record.stripe_product_id,
  expires_at: record.expires_at,
  expiring_7_days: data.expiring_7_days,
  expiring_today: data.expiring_today
}));

// ============================================
// PREPARE EXPIRED EVENT
// ============================================

const apiResponse = $input.first().json;
const batchItem = $('Process Expired').first().json;

const event = {
  event: 'course.access.expired',
  guild_id: batchItem.guild_id,
  timestamp: new Date().toISOString(),
  data: {
    user_id: batchItem.user_id,
    discord_id: batchItem.discord_id,
    course_id: batchItem.course_id,
    access_id: batchItem.access_id,
    expired_at: batchItem.expires_at
  }
};

return {
  access_id: batchItem.access_id,
  stream_name: 'learning:events:stream',
  event: event
};

// ============================================
// PREPARE WARNING NOTIFICATIONS
// ============================================

const catData = $('Categorize Expiring').first().json;

// Combine expiring today and 7 days for notifications
const toNotify = [
  ...catData.expiring_today.map(r => ({ ...r, notification_type: 'expires_today' })),
  ...catData.expiring_7_days.map(r => ({ ...r, notification_type: 'expires_soon' }))
];

if (toNotify.length === 0) {
  return { skip: true, job_id: catData.job_id };
}

return toNotify.map(record => ({
  job_id: catData.job_id,
  user_id: record.user_id,
  discord_id: record.discord_id,
  guild_id: record.guild_id,
  course_id: record.course_id,
  expires_at: record.expires_at,
  days_until: record.days_until,
  notification_type: record.notification_type
}));

// ============================================
// PREPARE WARNING EVENT
// ============================================

const record = $input.first().json;

const event = {
  event: 'course.access.expiring',
  guild_id: record.guild_id,
  timestamp: new Date().toISOString(),
  data: {
    user_id: record.user_id,
    discord_id: record.discord_id,
    course_id: record.course_id,
    expires_at: record.expires_at,
    days_until_expiration: record.days_until,
    notification_type: record.notification_type
  }
};

return {
  stream_name: 'learning:events:stream',
  event: event
};

// ============================================
// FINAL SUMMARY
// ============================================

const catData = $('Categorize Expiring').first().json;

console.log(`Expiration job completed: ${catData.job_id}`);
console.log(`  Total checked: ${catData.total_checked}`);
console.log(`  Expired: ${catData.expired_count}`);
console.log(`  Expiring today: ${catData.expiring_today_count}`);
console.log(`  Expiring in 7 days: ${catData.expiring_7_days_count}`);

return {
  job_id: catData.job_id,
  run_date: catData.run_date,
  summary: {
    total_checked: catData.total_checked,
    expired: catData.expired_count,
    expiring_today: catData.expiring_today_count,
    expiring_7_days: catData.expiring_7_days_count
  }
};
